import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import {
  Center,
  HStack,
  HTMLChakraProps,
  PlacementWithLogical,
  Popover,
  PopoverBody,
  PopoverContent,
  PopoverTrigger,
  Portal,
  Text,
  VStack
} from '@chakra-ui/react'

interface LabelInfo {
  label: string
  value: string
}

interface TooltipProps {
  content: string | React.ReactNode
  placement?: PlacementWithLogical
  xlinkHref?: string
}

interface TableSortThProps extends HTMLChakraProps<'div'> {
  labelInfo: LabelInfo
  tooltip?: TooltipProps
  sortRule: 'asc' | 'desc'
  sortBy: LabelInfo
  clickSort: (value: LabelInfo) => void
  labelFontSize?: string
  width?: string
  haveManySort?: boolean //当前列是否有超过一个排序
  appShowIcon?: boolean //h5页面是否需要sort icon
  showSortIcon?: boolean //多个页面共用一个table 部分页面不需要排序时 需要去掉sort icon
  defaultShowSortIcon?: boolean //一些页面需要一直展示排序icon 如仓位列表
}

export default function TableSortTh({
  labelInfo,
  tooltip,
  sortRule = 'desc',
  labelFontSize = '14px',
  appShowIcon = false,
  showSortIcon = true,
  sortBy,
  clickSort,
  width,
  haveManySort = true,
  defaultShowSortIcon = false,
  ...rest
}: TableSortThProps) {
  const { isApp } = useWindowWidth()

  const mergedTooltip: TooltipProps = {
    content: '',
    placement: 'top',
    xlinkHref: '#icon-icon_tips',
    ...tooltip
  }

  const hasSplitLabel = labelInfo.label.includes('/') && haveManySort && showSortIcon
  const splitLabels = hasSplitLabel ? labelInfo.label.split('/') : []
  const splitValues = hasSplitLabel ? labelInfo.value.split('/') : []

  const renderSortIcon = (value: string) => (
    <VStack h="20px" gap="0">
      <Icon
        xlinkHref="#icon-icon_ascending_nor"
        svgH="10px"
        svgHover="primary"
        svgFill={sortBy?.value === value && sortRule === 'asc' ? 'primary' : ''}
      />
      <Icon
        xlinkHref="#icon-icon_descending_nor"
        svgH="10px"
        svgHover="primary"
        svgFill={sortBy?.value === value && sortRule === 'desc' ? 'primary' : ''}
      />
    </VStack>
  )

  const renderLabel = (label: string, value: string) => (
    <HStack gap="0px" onClick={() => clickSort({ value, label })}>
      <Text
        fontSize={labelFontSize}
        _hover={{ color: 'text_caption' }}
        color={isApp && !appShowIcon ? 'text_paragraph' : sortBy?.value === value ? 'text_caption' : 'text_paragraph'}
      >
        {label}
      </Text>
      {(sortBy?.value === value || defaultShowSortIcon) && renderSortIcon(value)}
    </HStack>
  )

  return (
    <HStack w={width || 'unset'} mr="-4px" justify="flex-end" cursor={showSortIcon ? 'pointer' : 'text'} gap="0px" {...rest}>
      {/* 同一列有两个排序 */}
      {hasSplitLabel ? (
        <HStack gap="2px">
          {renderLabel(splitLabels[0], splitValues[0])}
          <Text fontSize={labelFontSize} color="text_paragraph">
            /
          </Text>
          {renderLabel(splitLabels[1], splitValues[1])}
        </HStack>
      ) : (
        <HStack gap="0px" onClick={showSortIcon ? () => clickSort(labelInfo) : () => {}}>
          <Text
            fontSize={labelFontSize}
            _hover={{ color: showSortIcon ? 'text_caption' : 'text_paragraph' }}
            color={isApp && !appShowIcon ? 'text_paragraph' : labelInfo.value === sortBy?.value ? 'text_caption' : 'text_paragraph'}
          >
            {labelInfo.label}
          </Text>
          {showSortIcon && (!isApp || appShowIcon) && (sortBy?.value === labelInfo.value || defaultShowSortIcon) && renderSortIcon(labelInfo.value)}
        </HStack>
      )}

      {mergedTooltip?.content && (
        <Popover isLazy trigger={isApp ? 'click' : 'hover'} placement={mergedTooltip?.placement}>
          <PopoverTrigger>
            <Center as="button" onClick={cancelBubble}>
              <Icon xlinkHref={mergedTooltip?.xlinkHref || ''} />
            </Center>
          </PopoverTrigger>
          <Portal>
            <PopoverContent w="fit-content" maxW="320px">
              <PopoverBody>
                {typeof mergedTooltip.content === 'string' ? (
                  <Text fontSize="12px" lineHeight="20px" dangerouslySetInnerHTML={{ __html: mergedTooltip.content }} />
                ) : (
                  <Text fontSize="12px" lineHeight="20px">
                    {mergedTooltip.content}
                  </Text>
                )}
              </PopoverBody>
            </PopoverContent>
          </Portal>
        </Popover>
      )}
    </HStack>
  )
}
